insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$morretes$q$, $q$https://www.diariomunicipal.com.br/amp/materia/66064380 (Decreto 426/2019, Diário Oficial dos Municípios do Paraná)$q$, $q$Ato oficial de Morretes: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 6, $q$Decreto 426/2019: proíbe veículos pesados (todos os caminhões exceto as classes 2C e 3C da Res. Contran 12/98) na Estrada de Barreiros. Risco residual: a base do decreto (art. 126 da LC 11/2011) foi revogada pela LC 64/2024, que não revogou o Decreto 426/2019 e mantém o poder de interditar ruas a caminhões (art. 102 §2º): confiança média. O alvo (eixos acima de 3 ou semirreboque/reboque/CVC) é aproximação das classes. Divergência do OSM registrada sem correção: maxweight 8,5 t na Estrada da Graciosa (PR-410, rodovia estadual, fora da competência municipal). Morretes não define VUC nos atos lidos.$q$);
